create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,guardian_consent boolean not null default false,access_approved boolean not null default false,created_at timestamptz not null default now());
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
create or replace function private.create_playground_profile() returns trigger language plpgsql security definer set search_path='' as $ begin insert into public.profiles(id,guardian_consent,access_approved) values(new.id,false,false) on conflict(id) do nothing; return new; end; $;
revoke all on function private.create_playground_profile() from public,anon,authenticated;
drop trigger if exists on_auth_user_created_playground on auth.users;
create trigger on_auth_user_created_playground after insert on auth.users for each row execute function private.create_playground_profile();
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'แชตใหม่' check(char_length(title)<=120),provider text not null default 'deepseek',model text not null default 'deepseek-flash',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists conversations_user_updated_idx on public.conversations(user_id,updated_at desc);
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('user','assistant')),content text not null check(char_length(content)<=20000),prompt_tokens integer,completion_tokens integer,created_at timestamptz not null default now());
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at);
create table if not exists public.usage_events(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,provider text not null,model text not null,created_at timestamptz not null default now());
create index if not exists usage_events_user_created_idx on public.usage_events(user_id,created_at desc);
alter table public.profiles enable row level security;alter table public.conversations enable row level security;alter table public.messages enable row level security;alter table public.usage_events enable row level security;
create policy "profile own read" on public.profiles for select to authenticated using((select auth.uid())=id);
create policy "conversation own select" on public.conversations for select to authenticated using((select auth.uid())=user_id);
create policy "conversation own insert" on public.conversations for insert to authenticated with check((select auth.uid())=user_id);
create policy "conversation own update" on public.conversations for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "conversation own delete" on public.conversations for delete to authenticated using((select auth.uid())=user_id);
create policy "message own select" on public.messages for select to authenticated using((select auth.uid())=user_id);
create policy "message own insert" on public.messages for insert to authenticated with check((select auth.uid())=user_id and exists(select 1 from public.conversations c where c.id=conversation_id and c.user_id=(select auth.uid())));
create policy "message own delete" on public.messages for delete to authenticated using((select auth.uid())=user_id);
revoke all on public.usage_events from anon,authenticated;
create or replace function public.consume_chat_quota(p_user_id uuid,p_max_hourly integer default 15) returns boolean language plpgsql security definer set search_path='' as $$ declare n integer; begin perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0)); select count(*) into n from public.usage_events where user_id=p_user_id and created_at>now()-interval '1 hour'; if n>=greatest(1,least(p_max_hourly,60)) then return false; end if; insert into public.usage_events(user_id,provider,model) values(p_user_id,'deepseek','deepseek-flash'); return true; end; $$;
revoke all on function public.consume_chat_quota(uuid,integer) from public,anon,authenticated;grant execute on function public.consume_chat_quota(uuid,integer) to service_role;
revoke insert,update,delete on public.profiles from anon,authenticated;\ngrant select on public.profiles to authenticated;\ngrant select,insert,update,delete on public.conversations,public.messages to authenticated;
